import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gemm_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_gemm(torch::Tensor A, torch::Tensor B);
"""

gemm_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Kernel: C = A * B
//   A : (M, K) row-major   (stride (K,1))
//   B : (K, N) row-major   (viewed logically as (N,K) with stride (1,N))
//   C : (M, N) row-major   (stride (N,1))
template <class TA, class TB, class TC, class DA, class DB, class DC>
__global__ static void
gemm_device(cute::Shape<int,int,int> shape_MNK,
            TA const* A, DA dA,
            TB const* B, DB dB,
            TC      * C, DC dC,
            int split_k)
{
  using namespace cute;
  // Full tensors
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(get<0>(shape_MNK), get<2>(shape_MNK)), dA); // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(get<1>(shape_MNK), get<2>(shape_MNK)), dB); // (N,K)
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(get<0>(shape_MNK), get<1>(shape_MNK)), dC); // (M,N)
  // CTA tile sizes
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<32>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{}); // (BLK_M,BLK_K,k)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{}); // (BLK_N,BLK_K,k)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{}); // (BLK_M,BLK_N)
  // Shared memory
  __shared__ TA smemA[128*32];
  __shared__ TB smemB[128*32];
  // sA: match A's global memory layout (row-major, K contiguous) so that
  // global->shared copies are coalesced and shared-memory accesses avoid
  // bank conflicts caused by a layout mismatch with the source tensor.
  Tensor sA = make_tensor(make_smem_ptr(smemA), make_shape(Int<128>{}, Int<32>{}), make_stride(Int<32>{}, Int<1>{}));
  // sB: B's contiguous mode in global memory is N (stride 1), which already
  // matches the default column-major shared-memory layout below.
  Tensor sB = make_tensor(make_smem_ptr(smemB), make_shape(Int<128>{}, Int<32>{}));
  // Thread layouts for loads (256 threads total)
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  // Thread layout for compute
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA = local_partition(sA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB = local_partition(sB, tB, threadIdx.x);
  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  // Split-K: each block along gridDim.z handles a contiguous chunk of
  // K-tiles. This turns a single, extremely long serial K-loop (which
  // left the GPU almost empty because the output grid is only 2x2) into
  // many concurrent blocks that each do a fraction of the work, then
  // atomically accumulate their partial sums into C.
  int K_TILE_TOTAL = size<2>(tAgA);
  int k_tiles_per_split = (K_TILE_TOTAL + split_k - 1) / split_k;
  int k_tile_start = blockIdx.z * k_tiles_per_split;
  int k_tile_end = k_tile_start + k_tiles_per_split;
  if (k_tile_end > K_TILE_TOTAL) k_tile_end = K_TILE_TOTAL;
  for (int k_tile = k_tile_start; k_tile < k_tile_end; ++k_tile) {
    copy(tAgA(_,_,k_tile), tAsA);
    copy(tBgB(_,_,k_tile), tBsB);
    cp_async_fence();
    cp_async_wait<0>();
    __syncthreads();
    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }
  // Epilogue: atomically accumulate this block's partial K-sum into C.
  // C was zero-initialized on the host so this is correct regardless of
  // how many split-K blocks contribute to a given output tile.
  CUTE_UNROLL
  for (int i = 0; i < size(tCrC); ++i) {
    atomicAdd(&tCgC(i), tCrC(i));
  }
}

// Host wrapper
torch::Tensor cute_gemm(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");

  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0)==K, "B.size(0) must equal K (A.size(1))");

  TORCH_CHECK(M % 128 == 0, "M must be divisible by 128");
  TORCH_CHECK(N % 128 == 0, "N must be divisible by 128");
  TORCH_CHECK(K % 32  == 0, "K must be divisible by 32");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::zeros({M, N}, A.options());

  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();

  // A: (M,K) row-major -> stride (K,1)
  auto dA = make_stride(K, Int<1>{});
  // B viewed logically as (N,K) with underlying (K,N) row-major storage -> stride (1,N)
  auto dB = make_stride(Int<1>{}, N);
  // C: (M,N) row-major -> stride (N,1)
  auto dC = make_stride(N, Int<1>{});

  auto shape_MNK = make_shape(M, N, K);
  // Split-K: M and N are small (256x256) relative to K (huge), so the
  // default grid (M/128 x N/128 = 4 blocks) drastically underutilizes the
  // GPU. Split the K dimension across additional blocks along gridDim.z
  // and accumulate partial results atomically to increase parallelism.
  int K_TILE_TOTAL = K / 32;
  int split_k = 64;
  if (split_k > K_TILE_TOTAL) split_k = K_TILE_TOTAL;
  if (split_k < 1) split_k = 1;
  dim3 dimBlock(256);
  dim3 dimGrid(M/128, N/128, split_k);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_device<<<dimGrid, dimBlock, 0, stream>>>(shape_MNK, ptrA, dA, ptrB, dB, ptrC, dC, split_k);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_gemm_ext = load_inline(
    name="cute_gemm_ext",
    cpp_sources=gemm_cpp_decl,
    cuda_sources=gemm_cuda_src,
    functions=["cute_gemm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B)
    with a large K dimension, using a custom tiled CUTE GEMM kernel.
    """
    def __init__(self) -> None:
        super(ModelNew, self).__init__()
        self._ext = cute_gemm_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_gemm(A.contiguous(), B.contiguous())

